CREATE TABLE IF NOT EXISTS gis_dataset_retrievals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES gis_authoritative_sources(id) ON DELETE CASCADE, source_url text NOT NULL, retrieved_at timestamptz NOT NULL DEFAULT now(), http_status integer, content_type text, content_length bigint, content_hash text, retrieval_status text NOT NULL DEFAULT 'RETRIEVED', dataset_candidate text, metadata text, certification_status text NOT NULL DEFAULT 'UNVERIFIED', notes text);